WITH valid_subscriptions AS (SELECT *, ROUND(monthly_fee * 1.07, 2) AS adjusted_monthly_fee FROM subscriptions WHERE customer_id IN (8, 10, 12, 28)), status_summary AS (SELECT status, SUM(CASE WHEN status = 'CANCELLED' THEN 1 ELSE 0 END) AS cancelled_count FROM valid_subscriptions GROUP BY status) SELECT status, cancelled_count FROM status_summary WHERE cancelled_count > 58 ORDER BY cancelled_count
